function strength(pw) {
  const longEnough = pw.length >= 12;
  const hasDigit = /[0-9]/.test(pw);
  const hasSymbol = /[^a-zA-Z0-9]/.test(pw);
  return longEnough && hasDigit && hasSymbol ? "strong" : "weak";
}
console.log(strength("hunter2"));
console.log(strength("Correct-Horse-99!"));

